// MUST stay the first import: loads .env before any module reads process.env// at module-evaluation time. Moving it below other imports silently breaks// keys supplied via .env (they are captured as empty strings).import "./loadEnv";import express from "express";import type { Request, Response, NextFunction } from "express";import { providerHealthSafe } from "./providers/registry";import http from "http";import path from "path";import { WebSocketServer, WebSocket } from "ws";import { GoogleGenAI, Modality, Type, LiveServerMessage, LiveConnectConfig, ActivityHandling, StartSensitivity, EndSensitivity } from "@google/genai";import dotenv from "dotenv";import * as fs from "fs";import { randomUUID } from "node:crypto";import dns from "node:dns/promises";import net from "node:net";import { execFileSync, spawn } from "node:child_process";import os from "node:os";import {   loadMemories,   saveMemories,   formatSystemInstructionsWithMemories,   processConversationSlice } from "./server_memory";import { MASTER_SYSTEM_PROMPT } from "./prompts/masterSystemPrompt";import { Memory } from "./src/lib/memoryTypes";import { registerAuthRoutes } from "./auth/authRoutes";import { requireAuth } from "./auth/authRoutes";import { requireOwner, requireAdminOrOwner } from "./auth/adminAuth";import { requireAdmin, resolveUserFromRequest, getAdmin } from "./auth/supabaseClient";import { registerMemoryRoutes } from "./auth/memoryRoutes";import { requireMemoryScope, resolveMemoryScopeFromRequest, type ScopedRequest } from "./auth/memoryScope";import { registerWorkspaceRoutes } from "./auth/workspaceRoutes";import { registerAccountRoutes } from "./auth/accountRoutes";import { registerGoogleRoutes } from "./auth/googleRoutes";import { registerAdminRoutes } from "./auth/adminRoutes";import { registerBillingRoutes } from "./auth/billingRoutes";import { syncPlatformOwners } from "./auth/ownerBootstrap";import { monitorChatMessage } from "./auth/safetyMonitor";import { listConnectedApps, listAppAc